/**
 * docs/COMMAND_REGISTRY.md drift guard.
 *
 * The doc drifted to v5.0.0 and omitted 33 registered commands (including `cat`
 * and `echo`) because its inventory was hand-maintained with no derivation from
 * the registry. The inventory is now generated by
 * `scripts/gen-command-registry.mjs` into a delimited block; this test is what
 * makes the drift impossible rather than merely fixed.
 *
 * The assertions are deliberately two-directional and have NO allowlist escape
 * hatch (unlike readme.test.ts, which exempts the `node` stub): a command added
 * to `commands/definitions/*.ts` without regenerating the doc fails here, and a
 * command deleted from the registry but left in the doc fails here too.
 *
 * Scope: only the generated block is compared. The doc's "Interpreter Builtins"
 * and "Agent Toolbox" sections are hand-authored and intentionally document
 * things that are NOT command-registry entries (`cd`, `export`, `[[`,
 * `ag-web-fetch`, ...), so including them would make set equality meaningless.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import {
  getCommandNames,
  getJavaScriptCommandNames,
  getNetworkCommandNames,
  getPythonCommandNames,
} from "./registry.js";

/** packages/bash/src/commands -> repo root */
const REPO_ROOT = path.join(import.meta.dirname, "..", "..", "..", "..");
const DOC_PATH = path.join(REPO_ROOT, "docs", "COMMAND_REGISTRY.md");

const BEGIN_MARKER = "<!-- BEGIN GENERATED: command-inventory -->";
const END_MARKER = "<!-- END GENERATED: command-inventory -->";

const TABLE_SEPARATOR_CELL = /^[\s:|-]+$/;
const BACKTICKED_TOKEN = /`([^`]+)`/g;
const RELATIVE_MD_LINK = /\]\((\.[^)]+\.md)\)/g;

function readDoc(): string {
  return fs.readFileSync(DOC_PATH, "utf-8");
}

/** Every name the command registry can dispatch, across all runtime gates. */
function registryCommands(): Set<string> {
  return new Set([
    ...getCommandNames(),
    ...getNetworkCommandNames(),
    ...getPythonCommandNames(),
    ...getJavaScriptCommandNames(),
  ]);
}

function generatedBlock(doc: string): string {
  const start = doc.indexOf(BEGIN_MARKER);
  const end = doc.indexOf(END_MARKER);
  if (start === -1 || end === -1 || end < start) {
    expect.fail(
      `docs/COMMAND_REGISTRY.md is missing the generated inventory markers.\n` +
        `Expected ${BEGIN_MARKER} ... ${END_MARKER}\n` +
        `Run: node scripts/gen-command-registry.mjs`,
    );
  }
  return doc.slice(start + BEGIN_MARKER.length, end);
}

/**
 * Command names documented in the generated block: the backticked tokens in the
 * first cell of every markdown table row.
 */
function documentedCommands(block: string): string[] {
  const names: string[] = [];
  for (const line of block.split("\n")) {
    if (!line.trimStart().startsWith("|")) continue;
    const firstCell = line.split("|")[1] ?? "";
    if (TABLE_SEPARATOR_CELL.test(firstCell)) continue;
    for (const match of firstCell.matchAll(BACKTICKED_TOKEN)) {
      names.push(match[1].trim());
    }
  }
  return names;
}

describe("docs/COMMAND_REGISTRY.md", () => {
  it("documents every registered command (nothing missing)", () => {
    const registry = registryCommands();
    const documented = new Set(documentedCommands(generatedBlock(readDoc())));

    const missing = [...registry].filter((n) => !documented.has(n)).sort();

    if (missing.length > 0) {
      expect.fail(
        `${missing.length} registered command(s) missing from ` +
          `docs/COMMAND_REGISTRY.md: ${missing.join(", ")}\n` +
          `Run: node scripts/gen-command-registry.mjs`,
      );
    }
  });

  it("documents only registered commands (nothing extra)", () => {
    const registry = registryCommands();
    const documented = new Set(documentedCommands(generatedBlock(readDoc())));

    const extra = [...documented].filter((n) => !registry.has(n)).sort();

    if (extra.length > 0) {
      expect.fail(
        `${extra.length} command(s) in the generated inventory of ` +
          `docs/COMMAND_REGISTRY.md are not in the registry: ${extra.join(", ")}\n` +
          `Either register them, or move them to a hand-authored section ` +
          `outside the generated block.`,
      );
    }
  });

  it("lists each command exactly once", () => {
    const names = documentedCommands(generatedBlock(readDoc()));
    const seen = new Set<string>();
    const duplicates = new Set<string>();
    for (const name of names) {
      if (seen.has(name)) duplicates.add(name);
      seen.add(name);
    }

    expect([...duplicates].sort()).toEqual([]);
  });

  it("has no dead relative links", () => {
    const doc = readDoc();
    const docDir = path.dirname(DOC_PATH);
    const dead: string[] = [];

    for (const match of doc.matchAll(RELATIVE_MD_LINK)) {
      const target = match[1];
      if (!fs.existsSync(path.resolve(docDir, target))) dead.push(target);
    }

    expect([...new Set(dead)].sort()).toEqual([]);
  });
});
